const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let films=[],saved=[],history={},view='movie',collection='popular',page=1,more=false,busy=false,requestId=0,active=null,debounce;try{saved=JSON.parse(localStorage.getItem('radha-full-list')||'[]');history=JSON.parse(localStorage.getItem('radha-full-progress')||'{}');if(!Array.isArray(saved))saved=[]}catch{saved=[];history={}}function persist(){try{localStorage.setItem('radha-full-list',JSON.stringify(saved));localStorage.setItem('radha-full-progress',JSON.stringify(history))}catch{}}function render(){const q=$('#search').value.trim().toLowerCase();const rows=view==='list'?saved.filter(f=>f.title.toLowerCase().includes(q)):films;$('#count').textContent=saved.length;$('#heading').textContent=view==='list'?'Your watchlist.':view==='tv'?'Find your next series.':'Your next movie night.';$('#results').textContent=busy?'Finding titles…':rows.length+' titles shown'+(more?' · more available':'');$('#grid').innerHTML=rows.map(f=>`<article class="card"><div class="poster">${f.image?`<img src="${esc(f.image)}" alt="${esc(f.title)} poster" loading="lazy">`:''}<span class="badge">${f.type==='series'?'SERIES':'MOVIE'}</span><button class="play" data-play="${esc(f.id)}" aria-label="Watch ${esc(f.title)}"><span class="postertitle">${esc(f.title)}</span></button><button class="save ${saved.some(x=>x.id===f.id)?'saved':''}" data-save="${esc(f.id)}" aria-label="Save ${esc(f.title)}">${saved.some(x=>x.id===f.id)?'✓':'＋'}</button></div><h3>${esc(f.title)}</h3><div class="cardmeta"><span>${esc(f.year||'Year unavailable')}</span><span>${f.type==='series'?'TV series':'Movie'}</span></div></article>`).join('');$('#empty').hidden=rows.length>0;$('#empty').textContent=busy?'Loading catalogue…':view==='list'?'Save a title with + to see it here.':'No matching titles. Try another search.';$('#more').hidden=!more||view==='list';$('#more').disabled=busy;$('#more').textContent=busy?'Loading…':'Load more titles';}async function load(append=false){if(view==='list'){requestId++;busy=false;more=false;render();return}const rid=++requestId;busy=true;if(!append){page=1;films=[]}render();try{let data;const q=$('#search').value.trim();if(collection==='hindi'&&!q&&view==='movie'){data={results:await(await fetch('hindi.json')).json(),hasMore:false}}else{const p=new URLSearchParams({type:view,page:String(page),sort:collection,q});const r=await fetch('/.netlify/functions/catalog?'+p);data=await r.json();if(!r.ok)throw Error(data.error||'Catalogue unavailable')}if(rid!==requestId)return;films=append?[...films,...data.results.filter(f=>!films.some(x=>x.id===f.id))]:data.results;more=data.hasMore;busy=false;render()}catch(e){if(rid!==requestId)return;busy=false;render();$('#empty').hidden=false;$('#empty').textContent='The catalogue could not load. '+e.message;$('#reset').hidden=false;$('#reset').textContent='Retry catalogue'}}function setView(v){view=v==='all'?'movie':v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',(b.dataset.view==='series'?'tv':b.dataset.view)===view));load()}function frame(){const season=Math.max(1,parseInt($('#season').value)||1),episode=Math.max(1,parseInt($('#episode').value)||1);$('#season').value=season;$('#episode').value=episode;const path=active.type==='series'?`tv/${active.tmdb}/${season}/${episode}`:`movie/${active.tmdb}`;const p=new URLSearchParams({color:'ED1935',episodeSelector:'true',nextEpisode:'true',autoplayNextEpisode:'true'});const pos=history[active.id];if(pos&&pos.season===season&&pos.episode===episode)p.set('progress',pos.time);const iframe=document.createElement('iframe');iframe.src='https://vidy.st/'+path+'?'+p;iframe.title=active.title+' video player';iframe.allow='encrypted-media; autoplay *; fullscreen *; picture-in-picture';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';$('#embedBox').replaceChildren(iframe)}function play(id){active=[...films,...saved].find(f=>f.id===id);if(!active)return;$('#playerTitle').textContent=active.title;$('#playerMeta').textContent=[active.year,active.type==='series'?'TV series':'Movie'].filter(Boolean).join(' · ');$('#description').textContent=active.description||'';$('#sourceLink').href=active.source;$('#tvControls').hidden=active.type!=='series';$('#season').value=history[id]?.season||1;$('#episode').value=history[id]?.episode||1;$('#player').showModal();frame()}$('#grid').onclick=e=>{const p=e.target.closest('[data-play]'),s=e.target.closest('[data-save]');if(p)play(p.dataset.play);if(s){const f=[...films,...saved].find(x=>x.id===s.dataset.save);if(saved.some(x=>x.id===f.id))saved=saved.filter(x=>x.id!==f.id);else saved.push(f);persist();render()}};$('#search').oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>load(),400)};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view==='series'?'tv':b.dataset.view));document.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>{collection=b.dataset.collection;document.querySelectorAll('[data-collection]').forEach(x=>x.classList.toggle('selected',x===b));if(collection==='hindi')view='movie';load()});$('#more').onclick=()=>{page++;load(true)};$('#reset').onclick=()=>{ $('#reset').hidden=true;load()};$('#browse').onclick=()=>{setView('movie');$('.library').scrollIntoView({behavior:'smooth'})};$('#browseTV').onclick=()=>{setView('tv');$('.library').scrollIntoView({behavior:'smooth'})};$('#loadEpisode').onclick=frame;$('#credits').onclick=()=>$('#creditsDialog').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#player').onclose=()=>{$('#embedBox').replaceChildren();active=null};window.addEventListener('message',e=>{const f=$('#embedBox iframe');if(!active||!f||e.source!==f.contentWindow||!['https://vidy.st','https://www.vidy.st'].includes(e.origin))return;try{const d=typeof e.data==='string'?JSON.parse(e.data):e.data;if(d.event==='timeupdate'&&Number.isFinite(d.currentTime)){history[active.id]={time:Math.floor(d.currentTime),season:Number($('#season').value),episode:Number($('#episode').value)};persist()}}catch{}});load();
